{"implementation":"import math

def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be an object')
    if 'nodes' not in case or 'core_distance' not in case or 'distances' not in case:
        raise ValueError('missing required field')
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    if not isinstance(nodes, list) or not isinstance(core, dict) or not isinstance(distances, list):
        raise ValueError('invalid required field type')
    if any(not isinstance(node, str) for node in nodes) or len(set(nodes)) != len(nodes):
        raise ValueError('nodes must be unique strings')
    node_set = set(nodes)
    if set(core) != node_set:
        raise ValueError('core_distance keys must match nodes')
    def valid_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value) and value >= 0
    if any(not valid_number(core[node]) for node in nodes):
        raise ValueError('invalid core distance')
    edges = []
    for item in distances:
        if not isinstance(item, list) or len(item) != 3:
            raise ValueError('invalid distance edge')
        left, right, distance = item
        if not isinstance(left, str) or not isinstance(right, str) or left == right:
            raise ValueError('invalid distance endpoints')
        if left not in node_set or right not in node_set or not valid_number(distance):
            raise ValueError('invalid distance edge')
        if right < left:
            left, right = right, left
        weight = max(core[left], core[right], distance)
        edges.append((weight, left, right))
    edges.sort(key=lambda edge: (edge[0], edge[1], edge[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node
    selected = []
    total = 0
    for weight, left, right in edges:
        root_left = find(left)
        root_right = find(right)
        if root_left == root_right:
            continue
        if rank[root_left] < rank[root_right]:
            root_left, root_right = root_right, root_left
        parent[root_right] = root_left
        if rank[root_left] == rank[root_right]:
            rank[root_left] += 1
        selected.append([left, right, weight])
        total += weight
        if len(selected) == len(nodes) - 1:
            break
    if len(selected) != max(0, len(nodes) - 1):
        raise ValueError('disconnected input')
    return {'mst_edges': selected, 'total_weight': total}
